    /// <summary>
    /// Fetches preview_url + tags for the installed mods in one batched API
    /// call, downloads any missing thumbnails into the cache (throttled), then
    /// rebuilds the tag sidebar. Runs in the background; grids/tiles update in
    /// place because ThumbnailPath raises PropertyChanged.
    /// </summary>
    private async Task LoadInstalledVisualsAsync()
    {
        try
        {
            var mods = _downloadedMods.ToList();
            if (mods.Count == 0) { RebuildTagSidebar(); return; }

            var visuals = await WorkshopVisualService.GetVisualsAsync(mods.Select(m => m.Id));

            await Task.WhenAll(mods.Select(async m =>
            {
                if (!visuals.TryGetValue(m.Id, out var v)) return;
                m.Tags = v.Tags;
                await ThumbnailGate.WaitAsync();
                try
                {
                    m.ThumbnailPath = await ThumbnailStore.GetOrDownloadAsync(m.Id, v.PreviewUrl);
                }
                finally
                {
                    ThumbnailGate.Release();
                }
            }));

            await Dispatcher.InvokeAsync(RebuildTagSidebar);
            AppendLog($"Loaded previews/tags for {mods.Count} installed mod(s).");
        }
        catch (Exception ex)
        {
            AppendLog($"Could not load mod visuals: {ex.Message}", "WARNING");
        }
    }

    private async Task LoadDownloadsThumbnailsAsync()
    {
        try
        {
            var tasks = _downloads.Where(t => !string.IsNullOrEmpty(t.Id)).Select(t => t.Id).Distinct().ToList();
            if (tasks.Count == 0) return;
            var visuals = await WorkshopVisualService.GetVisualsAsync(tasks);

            await Task.WhenAll(_downloads.Select(async t =>
            {
                if (!visuals.TryGetValue(t.Id, out var v)) return;
                await ThumbnailGate.WaitAsync();
                try
                {
                    t.ThumbnailPath = await ThumbnailStore.GetOrDownloadAsync(t.Id, v.PreviewUrl);
                }
                finally
                {
                    ThumbnailGate.Release();
                }
            }));
        }
        catch (Exception ex)
        {
            AppendLog($"Could not load download thumbnails: {ex.Message}", "WARNING");
        }
    }

