    /// <summary>
    /// Rebuilds the Installed Mods tag sidebar from the union of Steam tags
    /// across installed mods, preserving whatever filters were already checked.
    /// </summary>
    private void RebuildTagSidebar()
    {
        var tags = _downloadedMods.SelectMany(m => m.Tags)
            .Where(t => !string.IsNullOrWhiteSpace(t))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(t => t, StringComparer.OrdinalIgnoreCase)
            .ToList();

        var kept = _selectedTags.Where(t => tags.Contains(t, StringComparer.OrdinalIgnoreCase)).ToList();

        TagFilterPanel.Children.Clear();
        foreach (var tag in tags)
        {
            var cb = new CheckBox
            {
                Content = tag,
                Tag = tag,
                IsChecked = kept.Contains(tag, StringComparer.OrdinalIgnoreCase),
                Margin = new Thickness(0, 2, 0, 2),
            };
            cb.SetResourceReference(Control.ForegroundProperty, "FgText");
            cb.Checked += TagFilter_Changed;
            cb.Unchecked += TagFilter_Changed;
            TagFilterPanel.Children.Add(cb);
        }

        TagCountText.Text = $"{tags.Count} tag(s)";
        _selectedTags.Clear();
        foreach (var t in kept) _selectedTags.Add(t);
        ApplyInstalledTagFilter();
    }

    private void TagFilter_Changed(object? sender, RoutedEventArgs e)
    {
        if (sender is not CheckBox { Tag: string tag } cb) return;
        if (cb.IsChecked == true) _selectedTags.Add(tag);
        else _selectedTags.Remove(tag);
        ApplyInstalledTagFilter();
    }

    /// <summary>
    /// Filters the installed-mod collection through the shared collection view
    /// so the list grid AND the tile view update together. A mod is shown when
    /// no filters are selected, or when it matches any selected tag. Mods with
    /// no tag data stay visible so nothing gets hidden by accident.
    /// </summary>
    private void ApplyInstalledTagFilter()
    {
        var view = CollectionViewSource.GetDefaultView(_downloadedMods);
        view.Filter = _selectedTags.Count == 0 ? null :
            o => o is ModRecord m && (m.Tags.Count == 0 || m.Tags.Any(t => _selectedTags.Contains(t)));
    }

