    }

    private void UninstallMod_Click(object sender, RoutedEventArgs e)
    {
        if (sender is not FrameworkElement fe || fe.Tag is not ModRecord mod) return;

        var confirm = MessageBox.Show(
            $"Uninstall \"{mod.ModName}\"?\n\nThe mod folder will be deleted. " +
            "You can reinstall it later from the Uninstalled Mods tab.",
            "Confirm Uninstall", MessageBoxButton.YesNo, MessageBoxImage.Warning);
        if (confirm != MessageBoxResult.Yes) return;

        try
        {
            var path = Path.Combine(_settings.ModsFolder, mod.Folder);
            if (Directory.Exists(path)) Directory.Delete(path, recursive: true);
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not delete folder: {ex.Message}");
            AppendLog($"FAILED to uninstall {mod.ModName}: {ex.Message}", "ERROR");
            return;
        }

        _uninstalledMods.Insert(0, new UninstalledModEntry
        {
            Id = mod.Id,
            ModName = mod.ModName,
            Author = mod.Creator,
            UninstallDate = DateTime.Now.ToString("dd-MMM-yy h:mm:ss tt"),
        });
        UninstalledModsStore.Save(_uninstalledMods.ToList());

        AppendLog($"Uninstalled: {mod.ModName}");
        StatusText.Text = $"Uninstalled: {mod.ModName}";
        _ = RefreshDownloadedModsAsync();
    }

